import json,html
S=[ # id, السطر كما يظهر, متى يظهر, نص الحديث, الراوي, المصدر, الدرجة, ملاحظتي, جديد؟
('mon','غدًا الاثنين: كان النبي ﷺ يتحرّى صيامه  /  غدًا الخميس: كان النبي ﷺ يتحرّى صيامه','الأحد والأربعاء (تنبيه على صيام الغد)','كان النبي ﷺ يتحرّى صوم الاثنين والخميس.','عائشة','الترمذي (745)','حسن — قال الترمذي: حسن غريب','',False),
('bid','غدًا أول الأيام البيض: كان ﷺ يوصي بصيامها  /  غدًا من الأيام البيض…','الأيام 12 و13 و14 من كل شهر هجري (تنبيه على صيام الغد: 13 و14 و15)','«يا أبا ذرّ، إذا صمت من الشهر ثلاثة أيام فصم ثلاث عشرة وأربع عشرة وخمس عشرة».','أبي ذرّ','الترمذي (761)','حسن — الترمذي','اقتراح أدقّ للفظ: «غدًا أول الأيام البيض: أوصى النبي ﷺ بصيامها»؛ لأن الحديث وصية لأبي ذرّ لا خبر عن عادة دائمة.',False),
('arafa','غدًا يوم عرفة: صيامه يكفّر السنة التي قبله والتي بعده','8 ذي الحجة','«صيام يوم عرفة أحتسب على الله أن يكفّر السنة التي قبله والسنة التي بعده، وصيام يوم عاشوراء أحتسب على الله أن يكفّر السنة التي قبله».','أبي قتادة','مسلم (1162)','صحيح — مسلم','',False),
('tasua','غدًا التاسع من محرّم: «لئن بقيت إلى قابل لأصومنّ التاسع»','8 محرّم','«لئن بقيت إلى قابل لأصومنّ التاسع».','ابن عباس','مسلم (1134)','صحيح — مسلم','',False),
('ashura','غدًا عاشوراء: صيامه يكفّر السنة التي قبله','9 محرّم','(حديث أبي قتادة نفسه في عرفة)','أبي قتادة','مسلم (1162)','صحيح — مسلم','',False),
('shawwal','ستّ من شوّال: من صامها بعد رمضان كان كصيام الدهر','من 2 إلى 29 شوّال','«من صام رمضان ثم أتبعه ستًّا من شوّال كان كصيام الدهر».','أبي أيوب الأنصاري','مسلم (1164)','صحيح — مسلم','',False),
('ashr','أيام العشر: ما العمل الصالح في أيام أفضل منه فيها','من 1 إلى 9 ذي الحجة','«ما العمل في أيام العشر أفضل من العمل في هذه». قالوا: ولا الجهاد؟ قال: «ولا الجهاد، إلا رجل خرج يخاطر بنفسه وماله فلم يرجع بشيء».','ابن عباس','البخاري (969)','صحيح — البخاري','اقتراح أقرب إلى لفظ الحديث: «أيام العشر: ما العمل في أيام أفضل من العمل فيها».',False),
('jumua','اليوم الجمعة: خير يوم طلعت عليه الشمس','كل جمعة','«خير يوم طلعت عليه الشمس يوم الجمعة، فيه خُلق آدم، وفيه أُدخل الجنة، وفيه أُخرج منها».','أبي هريرة','مسلم (854)','صحيح — مسلم','',False),
('qadr','العشر الأواخر: تحرّوا ليلة القدر في الوتر منها','من 20 إلى 29 رمضان','«تحرّوا ليلة القدر في الوتر من العشر الأواخر من رمضان».','عائشة','البخاري (2017)','صحيح — البخاري','مقترحة جديدة: رمضان لا تنبيه فيه الآن على الصيام (كله صيام)، وهذه سنّته الخاصة.',True),
('shaban','شعبان: كان النبي ﷺ يصوم أكثره','من 1 إلى 28 شعبان','قالت: «ولم أره صائمًا من شهر قطّ أكثر من صيامه من شعبان، كان يصوم شعبان إلا قليلًا».','عائشة','مسلم (1156)','صحيح — مسلم','مقترحة جديدة. لا تظهر في آخر يوم أو يومين حتى لا تخالف النهي عن تقدّم رمضان بصوم يوم أو يومين (البخاري 1914).',True),
('muharram','شهر الله المحرّم: أفضل الصيام بعد رمضان','من 1 إلى 7 محرّم','«أفضل الصيام بعد رمضان شهر الله المحرّم، وأفضل الصلاة بعد الفريضة صلاة الليل».','أبي هريرة','مسلم (1163)','صحيح — مسلم','مقترحة جديدة: قبل تنبيه التاسع وعاشوراء.',True),
]
json.dump([dict(zip('id line when matn narr source grade note new'.split(),x)) for x in S],open('review1.json','w'),ensure_ascii=False,indent=1)
src=open('../seerah/review1.html').read()
css=src[src.index('<style>'):src.index('</style>')]+"""
.face{border-color:#0f5c4d;text-align:right;padding:16px 18px 12px}
.ln{font-family:var(--body);font-size:1.12rem;color:#0f5c4d;font-weight:600;margin:.2em 0 .4em}
.when{font-size:.82rem;color:#7a5b12;background:#f3e5bf;border-radius:99px;padding:1px 10px;display:inline-block}
.orig{border-top:1px dashed #d8ccb0;margin-top:10px;padding-top:8px;font-size:.92rem;color:#3c382c}
.o{font-family:var(--serif);font-size:1.05rem}
.newtag{background:#0f5c4d;color:#fff;border-radius:99px;font-size:.75rem;padding:1px 9px;margin-inline-start:6px}
</style>"""
script=src[src.index('<script>'):].replace('db.collection("seerah1")','db.collection("sunan1")')
o=['<title>سنن الأيام: مراجعة النصوص</title>\n<meta name="claude:viewport-fit-sides" content="cover">\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&family=Noto+Naskh+Arabic:wght@400;600&display=swap">',css,'<div class="wrap">',
'<header><h1>سنن الأيام: مراجعة النصوص</h1><div>السطر الذي يظهر تحت خط الصلاة، ومتى يظهر، والحديث الذي يُفتح حين يلمسه الشخص.</div></header>',
'<div class="how"><b>كيف تراجع:</b> تحت كل سطر: «موافق»، أو «أغيّر» واكتب التعديل، أو «ملاحظة». يُحفظ اختيارك فورًا، وما لم تختر فيه شيئًا يُعدّ مقبولًا. الثمانية الأولى في نسخة التجربة الآن، والثلاثة الأخيرة مقترحة جديدة.</div>',
'<div class="note"><b>ما تحقّقتُ منه:</b> نص كل حديث ورقمه من نسخ الصحيحين والترمذي، ودرجتا الترمذي من كلامه عقب الحديثين. <b>قاعدة العرض:</b> سطر واحد ظاهر بلا مصدر، ويأخذ مكانه حين تُنجَز المهمة الخفيّة (قرارك)؛ وإن اجتمع سطران في يوم تبدّلا كل ست ثوانٍ. لا تنبيه على صيام غدٍ إن كان رمضان أو عيدًا أو من أيام التشريق.</div>']
for x in json.load(open('review1.json')):
  nt=f'<div class="note"><b>ملاحظتي:</b> {html.escape(x["note"])}</div>' if x['note'] else ''
  o.append(f'<article class="q"><div class="face"><span class="when">يظهر: {html.escape(x["when"])}</span>{"<span class=newtag>مقترحة</span>" if x["new"] else ""}<p class="ln">✦ {html.escape(x["line"])}</p><div class="orig"><div>حين يُلمس يظهر:</div><div class="o">{html.escape(x["matn"])}</div><div class="src">عن {html.escape(x["narr"])} — {html.escape(x["source"])}</div><div class="grade">{html.escape(x["grade"])}</div></div></div>{nt}<div class="dec" data-id="{x["id"]}"><div class="btns"><button data-v="ok">موافق</button><button data-v="change">أغيّر</button><button data-v="note">ملاحظة</button></div><textarea id="n-{x["id"]}" placeholder="اكتب التعديل أو الملاحظة هنا" hidden></textarea><div class="st" aria-live="polite"></div></div></article>')
o.append('</div>'+script)
open('review1.html','w').write('\n'.join(o)); print('ok')
